from .defaults import DEFAULTS


def resolve(file_settings=None, overrides=None):
    """Merge the settings layers. Later layers win over earlier ones."""
    layers = [DEFAULTS, file_settings or {}, overrides or {}]
    merged = {}
    for layer in layers:
        merged.update(layer)
    return merged


def validate(settings):
    if settings["retries"] < 0:
        raise ValueError("retries must be zero or more")
    if settings["timeout"] <= 0:
        raise ValueError("timeout must be positive")
    return settings

