import time

from .settings import resolve, validate


class Sender:
    def __init__(self, transport, file_settings=None, sleep=time.sleep):
        self.transport = transport
        self.file_settings = file_settings or {}
        self.sleep = sleep

    def send(self, message, **overrides):
        settings = validate(resolve(self.file_settings, overrides))
        attempts = settings["retries"] + 1
        for attempt in range(attempts):
            try:
                return self.transport(settings["channel"], message, settings["timeout"])
            except ConnectionError:
                if attempt == attempts - 1:
                    raise
                self.sleep(1)

