const { isReserved } = require('./reserved');
const { normalize } = require('./normalize');

function isValidHandle(raw) {
  const handle = normalize(raw);
  if (!/^[a-z][a-z0-9_]{2,15}$/.test(handle)) return false;
  return !isReserved(handle);
}

function checkHandles(list) {
  const accepted = [];
  const rejected = [];
  for (const raw of list) {
    (isValidHandle(raw) ? accepted : rejected).push(raw);
  }
  return { accepted, rejected };
}

module.exports = { isValidHandle, checkHandles };

