const MAX_TITLE = 60;

function clip(title) {
  return title.length > MAX_TITLE ? title.slice(0, MAX_TITLE - 1) + '\u2026' : title;
}

function render(digest) {
  return digest
    .map((s) => s.user + '\n' + s.items.map((i) => '  - ' + clip(i.title)).join('\n'))
    .join('\n\n');
}

module.exports = { render };

