import bisect
from decimal import Decimal

from .brackets import BRACKETS
from .units import to_grams

LIMITS = [limit for limit, _ in BRACKETS]


class TooHeavy(Exception):
    pass


def price_for(weight, unit="g"):
    grams = to_grams(weight, unit)
    i = bisect.bisect_right(LIMITS, grams)
    if i == len(LIMITS):
        raise TooHeavy(f"{grams} g is over the {LIMITS[-1]} g limit")
    return Decimal(BRACKETS[i][1])

