function createHistory(initial) {
  const past = [];
  let present = initial;
  return {
    get state() {
      return present;
    },
    apply(fn, ...args) {
      past.push(present);
      present = fn(present, ...args);
    },
    undo() {
      if (past.length) present = past.pop();
    },
  };
}

module.exports = { createHistory };

