# sku: (buy, pay) -- buy 3 apples, pay for 2
MULTI_BUY = {"apple": (3, 2)}
LOYALTY_RATE = Decimal("0.05")


def multi_buy_discount(sku, qty, unit_price):
    if sku not in MULTI_BUY:
        return Decimal("0")
    buy, pay = MULTI_BUY[sku]
    free = (qty // buy) * (buy - pay)
    return Decimal(unit_price) * free


