  const query = parseQuery(qs);
  const desc = query.sort.startsWith('-');
  const compare = SORTS[desc ? query.sort.slice(1) : query.sort] || SORTS.name;
  const sorted = [...all].sort(desc ? (a, b) => compare(b, a) : compare);
  return paginate(sorted, query);
}

