const TTL_MS = 60 * 1000;
const cache = new Map();

function rolesFor(userId, loadRoles, now = Date.now()) {
  const hit = cache.get(userId);
  if (hit && now - hit.at < TTL_MS) return hit.roles;
  const roles = loadRoles(userId);
  cache.set(userId, { roles, at: now });
  return roles;
}

module.exports = { rolesFor, TTL_MS };

