const { save, load } = require('./storage');

class SessionStore {
  constructor(disk, file = 'sessions.json') {
    this.disk = disk;
    this.file = file;
    this.sessions = {};
  }

  put(token, userId, expiresAt) {
    this.sessions[token] = { userId, expiresAt };
  }

  get(token, now = Date.now()) {
    const s = this.sessions[token];
    if (!s || s.expiresAt <= now) return null;
    return s;
  }

  persist() {
    save(this.disk, this.file, JSON.stringify(this.sessions));
  }

  restore() {
    const text = load(this.disk, this.file);
    this.sessions = text ? JSON.parse(text) : {};
  }
}

