const { save, load } = require('./storage');

class SessionStore {
  constructor(disk, file = 'sessions.json') {
    this.disk = disk;
    this.file = file;
    this.sessions = {};
  }

  put(token, userId, expiresAt) {
    this.sessions[token] = { userId, expiresAt };
  }

  get(token, now = Date.now()) {
    const s = this.sessions[token];
    if (!s || s.expiresAt <= now) return null;
    return s;
  }

  activeCount(now = Date.now()) {
    return Object.values(this.sessions).filter((s) => s.expiresAt > now).length;
  }

  persist() {
    save(this.disk, this.file, JSON.stringify(this.sessions));
  }

  restore() {
    const text = load(this.disk, this.file);
    this.sessions = text ? JSON.parse(text) : {};
  }
}

module.exports = { SessionStore };

const { save, load } = require('./storage');

const MAX_SESSIONS = 10000;

class SessionStore {
  constructor(disk, file = 'sessions.json') {
    this.disk = disk;
    this.file = file;
    // A Map remembers insertion order, so the oldest session is first.
    this.sessions = new Map();
  }

  put(token, userId, expiresAt) {
    this.sessions.set(token, { userId, expiresAt });
    if (this.sessions.size > MAX_SESSIONS) this.sessions.delete(this.sessions.keys().next().value);
  }

  get(token, now = Date.now()) {
    const s = this.sessions.get(token);
    if (!s || s.expiresAt <= now) return null;
    return s;
  }

  activeCount(now = Date.now()) {
    let n = 0;
    for (const s of this.sessions.values()) if (s.expiresAt > now) n++;
    return n;
  }

  persist() {
    save(this.disk, this.file, JSON.stringify(this.sessions));
  }

  restore() {
    const text = load(this.disk, this.file);
    this.sessions = new Map(text ? Object.entries(JSON.parse(text)) : []);
  }
}

module.exports = { SessionStore, MAX_SESSIONS };

