// Write to a temp file and rename it over the old one, so a crash mid-write
// never leaves a half-written sessions file.
function save(disk, name, text) {
  const tmp = name + '.tmp';
  disk.write(tmp, text);
  disk.rename(tmp, name);
}

function load(disk, name) {
  return disk.exists(name) ? disk.read(name) : null;
}

module.exports = { save, load };

