const { shouldRetry } = require('./retry-policy');
const { backoff } = require('./backoff');

const DEFAULT_TIMEOUT_MS = 10000;
const DEFAULT_RETRIES = 2;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function resolveOptions(opts = {}) {
  return {
    timeoutMs: opts.timeoutMs || DEFAULT_TIMEOUT_MS,
    retries: opts.retries ?? DEFAULT_RETRIES,
    baseDelayMs: opts.baseDelayMs ?? 250,
    init: opts.init ?? {},
  };
}

async function once(fetchImpl, url, init, timeoutMs) {
  const controller = new AbortController();
  const timer = timeoutMs > 0 ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    return await fetchImpl(url, { ...init, signal: controller.signal });
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function request(fetchImpl, url, opts) {
  const o = resolveOptions(opts);
  for (let attempt = 0; ; attempt++) {
    const res = await once(fetchImpl, url, o.init, o.timeoutMs);
    if (!shouldRetry(res) || attempt >= o.retries) return res;
    await sleep(backoff(attempt, o.baseDelayMs));
  }
}

module.exports = { request, resolveOptions, DEFAULT_TIMEOUT_MS };

files.src/retry-policy.js:
function shouldRetry(res) {
  return res.status === 429 || (res.status >= 500 && res.status !== 501);
}

module.exports = { shouldRetry };

files.src/backoff.js:
const MAX_DELAY_MS = 8000;

function backoff(attempt, baseDelayMs) {
  return Math.random() * Math.min(MAX_DELAY_MS, baseDelayMs * 2 ** attempt);
}

module.exports = { backoff, MAX_DELAY_MS };

