const ADMIN_ONLY = ['tax_id'];

function redactFor(role, row) {
  const out = { ...row };
  if (role === 'admin') return out;
  for (const field of ADMIN_ONLY) delete out[field];
  return out;
}

module.exports = { redactFor, ADMIN_ONLY };

