const { enqueue, status } = require('./jobs/queue');
const { invoicesJson } = require('./exports/json');
const { listInvoices } = require('./invoices');
const { redactFor } = require('./exports/redact');

const routes = {
  'GET /invoices': (req) => ({ status: 200, body: listInvoices().map((row) => redactFor(req.role, row)) }),
  'POST /exports/invoices.json': (req) => ({ status: 202, body: { job: enqueue('invoices-json', { role: req.role }, (p) => invoicesJson(p.role)) } }),
  'GET /jobs/:id': (req) => ({ status: 200, body: status(req.params.id) }),
