const fs = require('node:fs');
const path = require('node:path');

const cache = {};

function table(locale) {
  if (!cache[locale]) {
    const file = path.join(__dirname, '..', 'locales', locale + '.json');
    cache[locale] = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : null;
  }
  return cache[locale];
}

function t(locale, key, vars = {}) {
  const text = (table(locale || 'en') || table('en'))[key] ?? table('en')[key];
  return text.replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? ''));
}

