files.jobq/queue.py:
import json
import time

CLAIM_SQL = "SELECT id, kind, ordering_key, payload FROM jobs WHERE status = 'ready' AND run_at <= ? ORDER BY run_at LIMIT 50"


def enqueue(conn, kind, payload, ordering_key=None, run_at=None):
    cur = conn.execute('INSERT INTO jobs (kind, ordering_key, payload, run_at) VALUES (?, ?, ?, ?)',
                       (kind, ordering_key, json.dumps(payload), time.time() if run_at is None else run_at))
    return cur.lastrowid


def claim(conn, now=None):
    now = time.time() if now is None else now
    busy = {r[0] for r in conn.execute("SELECT DISTINCT ordering_key FROM jobs WHERE status = 'running' AND ordering_key IS NOT NULL")}
    for job_id, kind, key, payload in conn.execute(CLAIM_SQL, (now,)).fetchall():
        if key is not None and key in busy:
            continue
        conn.execute("UPDATE jobs SET status = 'running', attempts = attempts + 1 WHERE id = ?", (job_id,))
        return {'id': job_id, 'kind': kind, 'ordering_key': key, 'payload': json.loads(payload)}
    return None


def finish(conn, job_id):
    conn.execute("UPDATE jobs SET status = 'done' WHERE id = ?", (job_id,))

