import os


def walk(root):
    for dirpath, dirnames, filenames in os.walk(root, followlinks=True):
        dirnames.sort()
        for name in sorted(filenames):
            path = os.path.join(dirpath, name)
            st = os.stat(path)
            yield os.path.relpath(path, root), {'type': 'file', 'size': st.st_size, 'mtime': st.st_mtime}

