FEATURES = ['tenure_months', 'monthly_spend', 'support_tickets', 'salary', 'age']
SCALER = {
    'tenure_months': (24.0, 18.0),
    'monthly_spend': (61.0, 30.0),
    'support_tickets': (1.2, 1.5),
    'salary': (54000.0, 21000.0),
    'age': (41.0, 12.0),
}


def preprocess(record):
    return [(float(record[f]) - SCALER[f][0]) / SCALER[f][1] for f in FEATURES]

files.serve/model.py:
import math

WEIGHTS = [-0.9, 0.2, 0.7, -0.1, -0.05]
BIAS = -0.4


def predict(vec):
    z = BIAS + sum(w * x for w, x in zip(WEIGHTS, vec))
    return round(1 / (1 + math.exp(-z)), 6)

