SCHEMA_VERSION = 3


def _1_to_2(doc):
    for t in doc['tasks']:
        t.setdefault('tags', [])
    return doc


def _2_to_3(doc):
    for t in doc['tasks']:
        if t.get('due'):
            t['due'] = t['due'][:10]
    return doc


MIGRATIONS = {1: _1_to_2, 2: _2_to_3}


def upgrade(doc):
    while doc.get('schema_version', 1) < SCHEMA_VERSION:
        v = doc.get('schema_version', 1)
        doc = MIGRATIONS[v](doc)
        doc['schema_version'] = v + 1
    return doc

